select count(1) from PRD_PLAN_INFO
(DATE_FORMAT(VDATE,'%Y-%m-%d') = #{planningStartDate} AND DATE_FORMAT(EDATE,'%Y-%m-%d') = #{planningEndDate})
AND PRD_PLAN_CODE <> #{planningNo}

select count(1) from PRD_PLAN_INFO
( (DATE_FORMAT(VDATE,'%Y-%m-%d') > #{planningStartDate} AND DATE_FORMAT(VDATE,'%Y-%m-%d') < #{planningEndDate}) or (DATE_FORMAT(EDATE,'%Y-%m-%d') > #{planningStartDate} AND DATE_FORMAT(EDATE,'%Y-%m-%d') < #{planningEndDate}) or (DATE_FORMAT(VDATE,'%Y-%m-%d') < #{planningStartDate} AND DATE_FORMAT(EDATE, '%Y-%m-%d') > #{planningEndDate}) )
AND PRD_PLAN_CODE <> #{planningNo}

mapper.update:
update PRD_PLAN_INFO set BENCH_DATE = #{baseDate,jdbcType=VARCHAR}, VDATE = #{planningStartDate,jdbcType=VARCHAR}, EDATE = #{planningEndDate,jdbcType=VARCHAR},
REMARK = #{remark,jdbcType=VARCHAR},
CREATE_USER = #{createUser,jdbcType=VARCHAR}, CREATE_DEPT = #{createDept,jdbcType=VARCHAR}, CREATE_TIME = STR_TO_DATE(NOW()), UPDATE_USER=#{updateUser,jdbcType=VARCHAR}, UPDATE_TIME= STR_TO_DATE(NOW()) where PRD_PLAN_CODE = #{planningNo,jdbcType=VARCHAR}
